98	function rodarTestes(cwd, arquivos, cmd, stackPython, resolver = resolverPython) {
99	  if (cmd) {
100	    const r = spawnSync(cmd, { cwd, shell: true, encoding: 'utf8', timeout: 600_000, env: envSemGit() });
101	    return { ok: r.status === 0, saida: ((r.stdout || '') + (r.stderr || '')).trim().split('\n').slice(-6).join('\n') };
102	  }
103	  // Adaptação local (2026-09-11): rotear POR EXTENSÃO, não só pela stack do projeto. Este repositório é
104	  // Python, mas a própria esteira traz um teste Node (tests/esteira.test.mjs). Mandar um `.mjs` para o
105	  // pytest fazia ele coletar zero testes e sair 4 — que o guard traduzia como "pytest não instalado",
106	  // mandando instalar uma ferramenta que não faltava. Agora: `.py` vai para o pytest; o resto, para o
107	  // `node --test`. Reportado ao kit.
