133	 *  `FERRAMENTA_AUSENTE` sempre, mesmo com o `.venv` do repo real instalado e funcionando. Réplica passa
134	 *  a compartilhar o MESMO `.venv` do repositório real (limite declarado na certidão do topo do arquivo)
135	 *  — aceitável porque o teste só LÊ o venv. Extraída como função à parte (BANCA SUBSTITUIR/testar sem
136	 *  precisar de Python de verdade instalado — só dois diretórios quaisquer e um arquivo-marcador). */
137	function linkarVenvNaReplica(repo, replica) {
138	  const venv = join(repo, '.venv');
139	  if (existsSync(venv) && !existsSync(join(replica, '.venv'))) {
140	    try { execFileSync('cmd', ['/c', 'mklink', '/J', join(replica, '.venv'), venv], { stdio: 'ignore' }); } catch { /* ignora-de-proposito: sem junction: cai pro python/py do sistema */ }
141	  }
142	}
