145	 * Mede de verdade: diff base...HEAD (+ index), réplica na base com os testes do HEAD, duas rodadas.
146	 * @returns {{estado, motivo, testes, fontes, saidaBase?, saidaHead?}}
147	 */
148	export function medir({ repo, base, cmd = null, incluirIndex = true } = {}) {
149	  const stackPython = stackDoProjeto(repo) === 'python'; // esteira.json inválido LANÇA → main() trata como NÃO MEDIU
150	  const mergeBase = git(['merge-base', base, 'HEAD'], repo);
151	  const doCommit = git(['diff', '--name-only', `${mergeBase}..HEAD`], repo).split('\n').filter(Boolean);
152	  const doIndex = incluirIndex ? git(['diff', '--name-only', '--cached'], repo).split('\n').filter(Boolean) : [];
153	  const arquivos = [...new Set([...doCommit, ...doIndex])];
154	  const { testes, fontes } = classificarDiff(arquivos, stackPython);
155	  if (testes.length === 0 || fontes.length === 0) return { ...julgar({ testes, fontes }), testes, fontes };
156	
157	  const replica = mkdtempSync(join(tmpdir(), 'crg-'));
158	  try {
159	    git(['worktree', 'add', '--detach', replica, mergeBase], repo);
160	    const nm = join(repo, 'node_modules');
161	    if (existsSync(nm) && !existsSync(join(replica, 'node_modules'))) {
162	      try { execFileSync('cmd', ['/c', 'mklink', '/J', join(replica, 'node_modules'), nm], { stdio: 'ignore' }); } catch { /* ignora-de-proposito: sem junction: o teste roda sem deps */ }
163	    }
164	    linkarVenvNaReplica(repo, replica);
165	    for (const t of testes) {
166	      const destino = join(replica, t);
167	      mkdirSync(dirname(destino), { recursive: true });
168	      if (existsSync(join(repo, t))) copyFileSync(join(repo, t), destino);
169	    }

